1	{
2	  "name": "quill-press",
3	  "version": "0.1.0",
4	  "private": true,
5	  "type": "module",
6	  "scripts": {
7	    "start": "node server.ts serve",
8	    "help": "node server.ts --help"
9	  }
10	}
11

1	import { createServer } from 'node:http';
2	import type { IncomingMessage, ServerResponse } from 'node:http';
3	import { mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs';
4	import { randomUUID } from 'node:crypto';
5	import { join } from 'node:path';
6	
7	const PRODUCT: string = 'QuillPress';
8	const RESOURCE: string = 'articles';
9	const MAX_BODY_BYTES: number = 5 * 1024 * 1024;
10	const PAGE: string = `<!doctype html>
11	<html lang="zh-CN">
12	<meta charset="utf-8">
13	<meta name="viewport" content="width=device-width,initial-scale=1">
14	<title>QuillPress · 内容编辑与刊物发布</title>
15	<style>
16	body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7;color:#1f2328}
17	a{color:#175b9c}
18	h2{margin-top:2rem}
19	form{border:1px solid #d0d7de;border-radius:8px;padding:1rem 1.25rem;margin:1rem 0 1.5rem}
20	form.editing{border-color:#175b9c;box-shadow:0 0 0 2px rgba(23,91,156,.15)}
21	label{display:block;font-weight:600;margin:.9rem 0 .3rem}
22	input[type=text],textarea{width:100%;box-sizing:border-box;font:inherit;padding:.5rem .6rem;border:1px solid #d0d7de;border-radius:6px;background:#fff;color:inherit}
23	textarea{resize:vertical}
24	button{margin-top:1.1rem;font:inherit;padding:.5rem 1.3rem;border-radius:6px;border:1px solid #175b9c;background:#175b9c;color:#fff;cursor:pointer}
25	button.secondary{background:#fff;color:#175b9c;margin-left:.6rem}
26	button:disabled{opacity:.55;cursor:default}
27	button.danger{border-color:#c0392b;background:#fff;color:#c0392b}
28	.status{margin:.8rem 0 0;min-height:1.4em}
29	.status.ok{color:#1a7f37}.status.err{color:#c0392b}.status.warn{color:#8a5a00}
30	.edit-banner{margin:0 0 .25rem;padding:.6rem .8rem;border-radius:6px;background:#eef4fb;border:1px solid #b6d2ee;color:#14467a;font-size:.92rem}
31	.edit-banner code{background:#dde9f6;padding:0 .3rem;border-radius:3px}
32	.edit-banner .meta{color:#3d6391;font-size:.85rem;margin-top:.2rem}
33	ul.articles{list-style:none;padding:0;margin:0}
34	article.draft{border:1px solid #d0d7de;border-radius:8px;padding:1rem 1.25rem;margin:1rem 0}
35	article.draft.editing{border-color:#175b9c;box-shadow:0 0 0 2px rgba(23,91,156,.15)}
36	.draft h3{margin:0 0 .4rem;word-break:break-word}
37	.draft .meta{color:#656d76;font-size:.85rem;margin:0 0 .5rem}
38	.draft .summary{white-space:pre-wrap;word-break:break-word;margin:0 0 .4rem;color:#3a4149}
39	.draft .actions{margin:.6rem 0 0}
40	.draft .actions button{margin:0;padding:.3rem .9rem;font-size:.88rem}
41	.draft .editing-tag{margin-left:.5rem;font-size:.78rem;font-weight:600;color:#175b9c;border:1px solid #175b9c;border-radius:999px;padding:0 .55rem;vertical-align:middle}
42	.empty{color:#656d76}
43	.empty.err{color:#c0392b}
44	.conflict{margin-top:1rem;border:1px solid #d9a441;border-radius:8px;background:#fffaf0;padding:1rem 1.25rem}
45	.conflict h3{margin:0 0 .3rem;color:#8a5a00;font-size:1.05rem}
46	.conflict .conflict-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-top:.7rem}
47	@media (max-width:46rem){.conflict .conflict-grid{grid-template-columns:1fr}}
48	.conflict .ver{border:1px solid #d0d7de;border-radius:6px;padding:.7rem .85rem;background:#fff;min-width:0}
49	.conflict .ver.saved{border-color:#8ab46a;background:#f6fbf2}
50	.conflict .ver h4{margin:0 0 .5rem;font-size:.92rem}
51	.conflict .ver dl{margin:0}
52	.conflict .ver dt{font-weight:600;font-size:.82rem;color:#57606a;margin-top:.5rem}
53	.conflict .ver dt:first-child{margin-top:0}
54	.conflict .ver dd{margin:.15rem 0 0;white-space:pre-wrap;word-break:break-word;font-size:.88rem;background:#f6f8fa;border-radius:4px;padding:.35rem .5rem;max-height:12rem;overflow:auto}
55	.conflict .ver.saved dd{background:#eef5e8}
56	.conflict .ver dd.empty-field{color:#8a8f98;font-style:italic;background:transparent;padding:0}
57	.conflict .actions{margin-top:.8rem}
58	.conflict .actions button{margin-top:0}
59	.conflict .actions .tip{font-size:.82rem;color:#8a5a00;margin-left:.6rem}
60	</style>
61	<main>
62	<h1>QuillPress</h1>
63	<p>内容编辑与刊物发布</p>
64	
65	<section aria-labelledby="compose-heading">
66	<h2 id="compose-heading">保存草稿</h2>
67	<form id="draft-form" autocomplete="off">
68	  <div id="edit-banner" class="edit-banner" hidden></div>
69	  <label for="title">标题</label>
70	  <input id="title" name="title" type="text">
71	  <label for="summary">摘要（可选）</label>
72	  <textarea id="summary" name="summary" rows="3"></textarea>
73	  <label for="body">正文</label>
74	  <textarea id="body" name="body" rows="10"></textarea>
75	  <button id="save-btn" type="submit">保存草稿</button>
76	  <button id="cancel-btn" class="secondary" type="button" hidden>取消编辑</button>
77	  <p id="status" class="status" role="status" aria-live="polite"></p>
78	  <div id="conflict-box" class="conflict" hidden></div>
79	</form>
80	</section>
81	
82	<section aria-labelledby="list-heading">
83	<h2 id="list-heading">草稿列表</h2>
84	<ul id="article-list" class="articles"></ul>
85	<p id="empty-tip" class="empty">草稿加载中…</p>
86	</section>
87	
88	<p><a href="/api/articles">查看文章列表接口</a> · <a href="/health">服务状态</a></p>
89	</main>
90	<script>
91	(function () {
92	  'use strict';
93	  var form = document.getElementById('draft-form');
94	  var titleInput = document.getElementById('title');
95	  var summaryInput = document.getElementById('summary');
96	  var bodyInput = document.getElementById('body');
97	  var saveBtn = document.getElementById('save-btn');
98	  var cancelBtn = document.getElementById('cancel-btn');
99	  var statusEl = document.getElementById('status');
100	  var editBanner = document.getElementById('edit-banner');
101	  var conflictBox = document.getElementById('conflict-box');
102	  var listEl = document.getElementById('article-list');
103	  var emptyTip = document.getElementById('empty-tip');
104	  var articles = [];
105	  var saving = false;
106	  // null = 新建草稿模式；对象 = 正在编辑的服务端版本 {id,title,summary,body,version}
107	  var editing = null;
108	
109	  function setStatus(text, kind) {
110	    statusEl.textContent = text || '';
111	    statusEl.className = 'status' + (kind ? ' ' + kind : '');
112	  }
113	  function setEmpty(text, kind) {
114	    emptyTip.textContent = text || '';
115	    emptyTip.className = 'empty' + (kind ? ' ' + kind : '');
116	    emptyTip.hidden = !text;
117	  }
118	  function hideConflict() {
119	    conflictBox.hidden = true;
120	    conflictBox.textContent = '';
121	  }
122	  function formatTime(iso) {
123	    var d = new Date(iso);
124	    return isNaN(d.getTime()) ? String(iso) : d.toLocaleString();
125	  }
126	  function render() {
127	    var sorted = articles.slice().sort(function (a, b) {
128	      var ta = a && a.createdAt ? String(a.createdAt) : '';
129	      var tb = b && b.createdAt ? String(b.createdAt) : '';
130	      if (ta !== tb) return ta < tb ? 1 : -1;
131	      return 0;
132	    });
133	    listEl.textContent = '';
134	    sorted.forEach(function (article) {
135	      var isEditing = editing && editing.id === article.id;
136	      var card = document.createElement('article');
137	      card.className = 'draft' + (isEditing ? ' editing' : '');
138	      var h = document.createElement('h3');
139	      h.textContent = article.title == null ? '' : String(article.title);
140	      if (isEditing) {
141	        var tag = document.createElement('span');
142	        tag.className = 'editing-tag';
143	        tag.textContent = '编辑中';
144	        h.appendChild(tag);
145	      }
146	      var meta = document.createElement('p');
147	      meta.className = 'meta';
148	      meta.textContent = '创建时间：' + formatTime(article.createdAt);
149	      var summary = document.createElement('p');
150	      summary.className = 'summary';
151	      var summaryText = article.summary == null ? '' : String(article.summary);
152	      summary.textContent = summaryText;
153	      card.appendChild(h);
154	      card.appendChild(meta);
155	      if (summaryText) card.appendChild(summary);
156	      var actions = document.createElement('p');
157	      actions.className = 'actions';
158	      var editBtn = document.createElement('button');
159	      editBtn.type = 'button';
160	      editBtn.className = 'secondary';
161	      editBtn.textContent = isEditing ? '正在编辑' : '编辑';
162	      editBtn.disabled = !!isEditing;
163	      editBtn.addEventListener('click', function () { startEdit(article.id); });
164	      actions.appendChild(editBtn);
165	      card.appendChild(actions);
166	      var li = document.createElement('li');
167	      li.appendChild(card);
168	      listEl.appendChild(li);
169	    });
170	    setEmpty(sorted.length === 0 ? '还没有保存的草稿。' : '');
171	  }
172	  function load() {
173	    return fetch('/api/articles', { headers: { accept: 'application/json' } })
174	      .then(function (r) {
175	        if (!r.ok) throw new Error('HTTP ' + r.status);
176	        return r.json();
177	      })
178	      .then(function (data) {
179	        articles = data && Array.isArray(data.articles) ? data.articles : [];
180	        render();
181	      })
182	      .catch(function (err) {
183	        articles = [];
184	        listEl.textContent = '';
185	        setEmpty('草稿列表加载失败：' + (err && err.message ? err.message : err), 'err');
186	      });
187	  }
188	
189	  function setSaving(on, label) {
190	    saving = on;
191	    saveBtn.disabled = on;
192	    saveBtn.textContent = label || (editing ? '保存修改' : '保存草稿');
193	    cancelBtn.disabled = on;
194	  }
195	
196	  function enterCreateMode(message, kind) {
197	    editing = null;
198	    form.reset();
199	    form.classList.remove('editing');
200	    editBanner.hidden = true;
201	    editBanner.textContent = '';
202	    hideConflict();
203	    cancelBtn.hidden = true;
204	    saveBtn.textContent = '保存草稿';
205	    setStatus(message || '', kind || '');
206	    render();
207	  }
208	
209	  function renderEditBanner(article) {
210	    editBanner.textContent = '';
211	    var line1 = document.createElement('div');
212	    line1.textContent = '正在编辑草稿：';
213	    var code = document.createElement('code');
214	    code.textContent = String(article.title);
215	    line1.appendChild(code);
216	    var line2 = document.createElement('div');
217	    line2.className = 'meta';
218	    line2.textContent = '创建时间：' + formatTime(article.createdAt) + ' · 标识：' + String(article.id);
219	    editBanner.appendChild(line1);
220	    editBanner.appendChild(line2);
221	  }
222	
223	  function applyEditingState(article) {
224	    editing = {
225	      id: article.id,
226	      title: article.title,
227	      summary: article.summary,
228	      body: article.body,
229	      version: article.version
230	    };
231	    titleInput.value = article.title == null ? '' : String(article.title);
232	    summaryInput.value = article.summary == null ? '' : String(article.summary);
233	    bodyInput.value = article.body == null ? '' : String(article.body);
234	    form.classList.add('editing');
235	    renderEditBanner(article);
236	    editBanner.hidden = false;
237	    cancelBtn.hidden = false;
238	    saveBtn.textContent = '保存修改';
239	    hideConflict();
240	    setStatus('已载入该草稿当前保存的内容，可以开始修改。', null);
241	    render();
242	    titleInput.focus();
243	  }
244	
245	  function isDirty() {
246	    if (!editing) {
247	      return titleInput.value !== '' || summaryInput.value !== '' || bodyInput.value !== '';
248	    }
249	    return titleInput.value !== editing.title
250	      || summaryInput.value !== editing.summary
251	      || bodyInput.value !== editing.body;
252	  }
253	
254	  function startEdit(id) {
255	    if (saving) return;
256	    if (isDirty() && !window.confirm('当前表单有未保存的修改，打开另一篇草稿将放弃这些输入。确定继续吗？')) {
257	      return;
258	    }
259	    // 记录开始读取时的表单快照。读取期间表单仍可继续输入，
260	    // 成功返回时据此判断是否有等待期间的新修改需要用户明确取舍。
261	    var snapshot = {
262	      title: titleInput.value,
263	      summary: summaryInput.value,
264	      body: bodyInput.value
265	    };
266	    setSaving(true, '读取中…');
267	    setStatus('正在读取草稿内容…', null);
268	    fetch('/api/articles/' + encodeURIComponent(id), { headers: { accept: 'application/json' } })
269	      .then(function (r) {
270	        return r.json().catch(function () { return null; }).then(function (data) {
271	          if (!r.ok || !data || !data.article) {
272	            throw new Error(data && data.error ? data.error : ('HTTP ' + r.status));
273	          }
274	          return data.article;
275	        });
276	      })
277	      .then(function (article) {
278	        setSaving(false);
279	        // 正文必须来自单篇接口，绝不使用列表里的摘要充当正文
280	        if (titleInput.value === snapshot.title
281	          && summaryInput.value === snapshot.summary
282	          && bodyInput.value === snapshot.body) {
283	          // 等待期间没有新修改（改动后又恢复原值也不算）：照常载入目标草稿
284	          applyEditingState(article);
285	          return;
286	        }
287	        // 等待期间有了新输入：绝不能直接回填覆盖。在用户明确选择之前，
288	        // 三个字段原样保留，表单仍处原先的新建或编辑原草稿状态，
289	        // 绝不把当前输入关联到目标文章。
290	        if (window.confirm('目标草稿已读取完成，但等待期间你又修改了标题、摘要或正文。'
291	          + '打开目标草稿将放弃这些新修改。\n\n'
292	          + '点击“确定”放弃新修改并打开目标草稿；点击“取消”保留当前输入，继续原来的操作。')) {
293	          applyEditingState(article);
294	        } else {
295	          setStatus('已保留当前输入，未打开目标草稿。', null);
296	        }
297	      })
298	      .catch(function (err) {
299	        setSaving(false);
300	        saveBtn.textContent = editing ? '保存修改' : '保存草稿';
301	        setStatus('打开草稿失败：' + (err && err.message ? err.message : err) + '，可稍后重试。', 'err');
302	      });
303	  }
304	
305	  cancelBtn.addEventListener('click', function () {
306	    if (saving || !editing) return;
307	    // 取消不提交任何修改，也不删除原文章，直接回到新建草稿状态
308	    if (isDirty() && !window.confirm('取消将放弃当前未保存的修改，原草稿不会被删除。确定取消编辑吗？')) {
309	      return;
310	    }
311	    enterCreateMode('已取消编辑，原草稿未改动。可以新建草稿。', null);
312	  });
313	
314	  function fieldValue(text, isEmpty) {
315	    var dd = document.createElement('dd');
316	    if (isEmpty) {
317	      dd.className = 'empty-field';
318	      dd.textContent = '（空）';
319	    } else {
320	      dd.textContent = text;
321	    }
322	    return dd;
323	  }
324	
325	  function showConflict(saved) {
326	    // 只展示对照，绝不重置表单、绝不自动重试覆盖
327	    conflictBox.textContent = '';
328	    var h = document.createElement('h3');
329	    h.textContent = '检测到较新的已保存内容';
330	    var p = document.createElement('p');
331	    p.textContent = '这篇草稿在其他页面已被修改并保存。为避免覆盖新版本，本次保存已被拒绝。你输入的内容仍保留在上方表单中，可对照右侧最新版本；只有明确放弃当前输入后，才会载入最新内容继续编辑。';
332	    conflictBox.appendChild(h);
333	    conflictBox.appendChild(p);
334	
335	    var grid = document.createElement('div');
336	    grid.className = 'conflict-grid';
337	
338	    var mine = document.createElement('div');
339	    mine.className = 'ver mine';
340	    var mineTitle = document.createElement('h4');
341	    mineTitle.textContent = '你正在编辑的内容（未保存）';
342	    mine.appendChild(mineTitle);
343	    var dl1 = document.createElement('dl');
344	    [['标题', titleInput.value, titleInput.value.trim() === ''],
345	     ['摘要', summaryInput.value, summaryInput.value === ''],
346	     ['正文', bodyInput.value, bodyInput.value === '']].forEach(function (pair) {
347	      var dt = document.createElement('dt');
348	      dt.textContent = pair[0];
349	      dl1.appendChild(dt);
350	      dl1.appendChild(fieldValue(pair[1], pair[2]));
351	    });
352	    mine.appendChild(dl1);
353	
354	    var theirs = document.createElement('div');
355	    theirs.className = 'ver saved';
356	    var tTitle = document.createElement('h4');
357	    tTitle.textContent = '最新已保存内容';
358	    theirs.appendChild(tTitle);
359	    var dl2 = document.createElement('dl');
360	    [['标题', saved.title, saved.title === ''],
361	     ['摘要', saved.summary, saved.summary === ''],
362	     ['正文', saved.body, saved.body === '']].forEach(function (pair) {
363	      var dt = document.createElement('dt');
364	      dt.textContent = pair[0];
365	      dl2.appendChild(dt);
366	      dl2.appendChild(fieldValue(pair[1], pair[2]));
367	    });
368	    theirs.appendChild(dl2);
369	
370	    grid.appendChild(mine);
371	    grid.appendChild(theirs);
372	    conflictBox.appendChild(grid);
373	
374	    var actions = document.createElement('p');
375	    actions.className = 'actions';
376	    var discard = document.createElement('button');
377	    discard.type = 'button';
378	    discard.className = 'danger';
379	    discard.textContent = '放弃当前输入并载入最新内容';
380	    discard.addEventListener('click', function () {
381	      applyEditingState(saved);
382	    });
383	    var keep = document.createElement('button');
384	    keep.type = 'button';
385	    keep.className = 'secondary';
386	    keep.textContent = '保留我的输入，继续修改';
387	    keep.addEventListener('click', function () {
388	      hideConflict();
389	      setStatus('已保留你的输入，请对照后手动调整再保存。', null);
390	      titleInput.focus();
391	    });
392	    var tip = document.createElement('span');
393	    tip.className = 'tip';
394	    tip.textContent = '不会自动覆盖或重置。';
395	    actions.appendChild(discard);
396	    actions.appendChild(keep);
397	    actions.appendChild(tip);
398	    conflictBox.appendChild(actions);
399	    conflictBox.hidden = false;
400	  }
401	
402	  form.addEventListener('submit', function (event) {
403	    event.preventDefault();
404	    if (saving) return;
405	    var trimmedTitle = titleInput.value.trim();
406	    if (!trimmedTitle) {
407	      setStatus('标题不能为空。', 'err');
408	      titleInput.focus();
409	      return;
410	    }
411	    hideConflict();
412	    var isEdit = !!editing;
413	    // 记录本次实际提交的原始字段值，响应返回时据此判断等待期间哪些字段又被编辑过。
414	    var submitted = {
415	      title: titleInput.value,
416	      summary: summaryInput.value,
417	      body: bodyInput.value
418	    };
419	    var payload = {
420	      title: titleInput.value,
421	      summary: summaryInput.value,
422	      body: bodyInput.value
423	    };
424	    var url = '/api/articles';
425	    if (isEdit) {
426	      url += '/' + encodeURIComponent(editing.id);
427	      payload.version = editing.version;
428	    }
429	    setSaving(true, '保存中…');
430	    setStatus(isEdit ? '正在保存修改…' : '正在保存…', null);
431	    fetch(url, {
432	      method: isEdit ? 'PUT' : 'POST',
433	      headers: { 'content-type': 'application/json', accept: 'application/json' },
434	      body: JSON.stringify(payload)
435	    })
436	      .then(function (r) {
437	        return r.json().catch(function () { return null; }).then(function (data) {
438	          return { status: r.status, data: data };
439	        });
440	      })
441	      .then(function (result) {
442	        var data = result.data;
443	        if (result.status === 409 && data && data.article) {
444	          // 版本冲突：保留表单全部输入，展示最新已保存内容供对照。
445	          // 绝不更新本地基准版本——只有用户显式确认载入最新内容后才允许覆盖。
446	          setSaving(false);
447	          saveBtn.textContent = editing ? '保存修改' : '保存草稿';
448	          setStatus('保存被拒绝：存在较新的已保存版本（409）。请对照后选择保留输入或载入最新内容。', 'err');
449	          showConflict(data.article);
450	          return;
451	        }
452	        if (result.status < 200 || result.status >= 300 || !data || !data.article) {
453	          throw new Error(data && data.error ? data.error : ('HTTP ' + result.status));
454	        }
455	        return data.article;
456	      })
457	      .then(function (article) {
458	        if (!article) return; // 冲突分支已处理
459	        if (isEdit) {
460	          var idx = -1;
461	          for (var i = 0; i < articles.length; i++) {
462	            if (articles[i] && articles[i].id === article.id) { idx = i; break; }
463	          }
464	          if (idx >= 0) articles[idx] = article; else articles.push(article);
465	          render();
466	          setSaving(false);
467	          // 保持编辑态：仍是同一篇草稿，可继续修改。
468	          // 成功只确认本次提交的内容；等待响应期间补写的字段原样保留，不被覆盖。
469	          mergeSavedEditingState(article, submitted);
470	        } else {
471	          // 新建成功：列表只显示本次实际保存的内容。若等待响应期间表单又被改过
472	          // 且未恢复为保存值，绝不能清空这些输入——把表单关联到刚创建的同一篇
473	          // 草稿进入编辑态，后续“保存修改”按本次响应的版本更新它，不再新建。
474	          articles.push(article);
475	          setSaving(false);
476	          if (hasUnsavedAfterSave(article, submitted)) {
477	            mergeSavedEditingState(article, submitted, true);
478	          } else {
479	            enterCreateMode('草稿已保存。可以继续新建草稿。', 'ok');
480	          }
481	        }
482	      })
483	      .catch(function (err) {
484	        setSaving(false);
485	        saveBtn.textContent = editing ? '保存修改' : '保存草稿';
486	        var prefix = isEdit ? '保存修改失败：' : '保存失败：';
487	        setStatus(prefix + (err && err.message ? err.message : err) + '，输入已保留，可处理后再次操作。', 'err');
488	      });
489	  });
490	
491	  function savedFieldList(article) {
492	    return [
493	      { key: 'title', label: '标题', el: titleInput, value: article.title == null ? '' : String(article.title) },
494	      { key: 'summary', label: '摘要', el: summaryInput, value: article.summary == null ? '' : String(article.summary) },
495	      { key: 'body', label: '正文', el: bodyInput, value: article.body == null ? '' : String(article.body) }
496	    ];
497	  }
498	
499	  // 是否仍有未保存内容，以当前表单与本次成功保存的内容是否相同为准：
500	  // 字段仍等于提交快照，或被改过又恢复为服务端保存值（如去首尾空白后的标题），
501	  // 都视为没有未保存修改。
502	  function hasUnsavedAfterSave(article, submitted) {
503	    return savedFieldList(article).some(function (f) {
504	      return f.el.value !== submitted[f.key] && f.el.value !== f.value;
505	    });
506	  }
507	
508	  // 保存成功后留在编辑态。成功响应只能确认本次提交的内容：
509	  // 服务端返回的已保存内容成为新的本地基准（version 一并推进，再次保存不会误报冲突），
510	  // 但等待响应期间用户继续输入过的字段必须保留当前值（含换行、空行与清空操作），
511	  // 绝不能用刚保存的旧值回填或替换。isCreate 表示这是新建草稿后的首次关联。
512	  function mergeSavedEditingState(article, submitted, isCreate) {
513	    var savedFields = savedFieldList(article);
514	    var editedWhileSaving = [];
515	    savedFields.forEach(function (f) {
516	      if (f.el.value === submitted[f.key]) {
517	        // 等待期间未再改动：同步为服务端保存的规范值（例如去首尾空白后的标题）。
518	        if (f.el.value !== f.value) f.el.value = f.value;
519	      } else {
520	        // 等待期间又被修改（包括清空摘要或正文）：保留当前输入，不动一个字符。
521	        // 仅当保留下来的当前值确实与本次已保存值不同时，才算仍有未保存修改。
522	        if (f.el.value !== f.value) editedWhileSaving.push(f.label);
523	      }
524	    });
525	    editing = {
526	      id: article.id,
527	      title: savedFields[0].value,
528	      summary: savedFields[1].value,
529	      body: savedFields[2].value,
530	      version: article.version
531	    };
532	    form.classList.add('editing');
533	    renderEditBanner(article);
534	    editBanner.hidden = false;
535	    cancelBtn.hidden = false;
536	    saveBtn.textContent = '保存修改';
537	    hideConflict();
538	    render();
539	    if (editedWhileSaving.length === 0) {
540	      setStatus(isCreate
541	        ? '草稿已保存。可以继续修改，也可以取消编辑后新建下一篇。'
542	        : '修改已保存。文章标识、创建时间与草稿状态均未改变。', 'ok');
543	    } else if (isCreate) {
544	      setStatus('本次提交的草稿已保存，列表显示的是实际保存的内容。但'
545	        + editedWhileSaving.join('、')
546	        + '在保存期间又被修改，这些新输入尚未保存；表单已关联到刚创建的这篇草稿，再次点击“保存修改”将更新同一篇。', 'warn');
547	    } else {
548	      setStatus('本次提交的内容已保存（文章标识、创建时间与草稿状态不变）。但'
549	        + editedWhileSaving.join('、')
550	        + '在保存期间又被修改，这些新输入尚未保存；再次点击“保存修改”才会一并存入同一篇草稿。', 'warn');
551	    }
552	  }
553	
554	  load();
555	})();
556	</script>
557	</html>`;
558	const args: string[] = process.argv.slice(2);
559	const help: string = `QuillPress - 内容编辑与刊物发布
560	Usage: node server.ts serve [--host ADDRESS] [--port PORT] [--data-dir DIRECTORY]
561	       node server.ts --help
562	Defaults: --host 127.0.0.1 --port 8080 --data-dir data
563	Port 0 selects an available port.
564	`;
565	if (args.length === 0 || args.includes('--help') || args.includes('-h')) {
566	  process.stdout.write(help);
567	  process.exit(args.length === 0 ? 2 : 0);
568	}
569	if (args.shift() !== 'serve') { console.error('Expected serve or --help'); process.exit(2); }
570	let host: string = '127.0.0.1';
571	let port: number = 8080;
572	let dataDir: string = 'data';
573	while (args.length) {
574	  const flag = args.shift();
575	  const value = args.shift();
576	  if (!value || !['--host', '--port', '--data-dir'].includes(flag ?? '')) {
577	    console.error('Each option must be --host, --port or --data-dir followed by a value'); process.exit(2);
578	  }
579	  if (flag === '--host') host = value;
580	  else if (flag === '--port') {
581	    if (!/^\d+$/.test(value) || Number(value) > 65535) { console.error('Port must be between 0 and 65535'); process.exit(2); }
582	    port = Number(value);
583	  } else dataDir = value;
584	}
585	mkdirSync(dataDir, { recursive: true });
586	const dataFile = join(dataDir, 'articles.json');
587	try { writeFileSync(dataFile, '[]\n', { flag: 'wx' }); } catch (error) {
588	  if (!(error instanceof Error && 'code' in error && error.code === 'EEXIST')) throw error;
589	}
590	
591	interface Article {
592	  id: string;
593	  title: string;
594	  summary: string;
595	  body: string;
596	  status: 'draft';
597	  createdAt: string;
598	  version: number;
599	}
600	interface StoredArticle {
601	  id?: unknown;
602	  title?: unknown;
603	  summary?: unknown;
604	  body?: unknown;
605	  status?: unknown;
606	  createdAt?: unknown;
607	  version?: unknown;
608	}
609	interface DraftInput {
610	  title: string;
611	  summary: string;
612	  body: string;
613	}
614	
615	class HttpError extends Error {
616	  status: number;
617	  constructor(status: number, message: string) {
618	    super(message);
619	    this.name = 'HttpError';
620	    this.status = status;
621	  }
622	}
623	
624	function respond(res: ServerResponse, status: number, value: unknown, html = false): void {
625	  const body = html ? String(value) : JSON.stringify(value);
626	  res.writeHead(status, {
627	    'content-type': html ? 'text/html; charset=utf-8' : 'application/json; charset=utf-8',
628	    'content-length': Buffer.byteLength(body),
629	  });
630	  res.end(body);
631	}
632	
633	function methodNotAllowed(res: ServerResponse, allow: string): void {
634	  const body = JSON.stringify({ error: 'method not allowed' });
635	  res.writeHead(405, {
636	    'content-type': 'application/json; charset=utf-8',
637	    'content-length': Buffer.byteLength(body),
638	    allow,
639	  });
640	  res.end(body);
641	}
642	
643	// Normalize a stored record. Drafts saved by older versions have no `version`
644	// field; those are treated as version 0 and can be opened and edited directly.
645	function normalizeArticle(record: unknown): Article | null {
646	  if (typeof record !== 'object' || record === null || Array.isArray(record)) return null;
647	  const r = record as StoredArticle;
648	  if (typeof r.id !== 'string' || typeof r.title !== 'string' || typeof r.body !== 'string') return null;
649	  if (r.status !== 'draft' || typeof r.createdAt !== 'string') return null;
650	  const version = typeof r.version === 'number' && Number.isInteger(r.version) && r.version >= 0 ? r.version : 0;
651	  return {
652	    id: r.id,
653	    title: r.title,
654	    summary: typeof r.summary === 'string' ? r.summary : '',
655	    body: r.body,
656	    status: 'draft',
657	    createdAt: r.createdAt,
658	    version,
659	  };
660	}
661	
662	function readArticles(): Article[] {
663	  let parsed: unknown;
664	  try {
665	    parsed = JSON.parse(readFileSync(dataFile, 'utf8'));
666	  } catch (error) {
667	    throw new Error(`unable to read articles: ${(error as Error).message}`);
668	  }
669	  if (!Array.isArray(parsed)) throw new Error('unable to read articles: stored data is not a list');
670	  const articles: Article[] = [];
671	  for (const record of parsed) {
672	    const article = normalizeArticle(record);
673	    if (article) articles.push(article);
674	  }
675	  return articles;
676	}
677	
678	function writeArticles(records: Article[]): void {
679	  const tmpFile = join(dataDir, `.articles.${process.pid}.tmp`);
680	  try {
681	    writeFileSync(tmpFile, `${JSON.stringify(records, null, 2)}\n`);
682	    renameSync(tmpFile, dataFile);
683	  } catch (error) {
684	    try { rmSync(tmpFile, { force: true }); } catch { /* best effort cleanup */ }
685	    throw new Error(`unable to save articles: ${(error as Error).message}`);
686	  }
687	}
688	
689	// Serialize read-modify-write so concurrent saves never lose or corrupt records.
690	let writeQueue: Promise<void> = Promise.resolve();
691	function enqueueWrite<T>(task: () => T): Promise<T> {
692	  const run = writeQueue.then(task);
693	  writeQueue = run.then(() => undefined, () => undefined);
694	  return run;
695	}
696	
697	function readBody(req: IncomingMessage): Promise<string> {
698	  return new Promise((resolve, reject) => {
699	    const chunks: Buffer[] = [];
700	    let size = 0;
701	    let settled = false;
702	    req.on('data', (chunk: unknown) => {
703	      if (settled) return;
704	      const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk));
705	      size += buf.length;
706	      if (size > MAX_BODY_BYTES) {
707	        settled = true;
708	        reject(new HttpError(400, 'request body is too large'));
709	        req.destroy();
710	        return;
711	      }
712	      chunks.push(buf);
713	    });
714	    req.on('end', () => {
715	      if (!settled) resolve(Buffer.concat(chunks).toString('utf8'));
716	    });
717	    req.on('error', (error: Error) => {
718	      if (!settled) reject(new HttpError(400, `could not read request body: ${error.message}`));
719	    });
720	  });
721	}
722	
723	function parseJsonObject(text: string): Record<string, unknown> {
724	  let payload: unknown;
725	  try {
726	    payload = JSON.parse(text);
727	  } catch (error) {
728	    throw new HttpError(400, `invalid JSON: ${(error as Error).message}`);
729	  }
730	  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
731	    throw new HttpError(400, 'request body must be a JSON object');
732	  }
733	  return payload as Record<string, unknown>;
734	}
735	
736	function validateDraftInput(data: Record<string, unknown>): DraftInput {
737	  if (typeof data.title !== 'string') {
738	    throw new HttpError(400, 'title must be a string');
739	  }
740	  const title = data.title.trim();
741	  if (title.length === 0) {
742	    throw new HttpError(400, 'title must not be empty or only whitespace');
743	  }
744	  let summary = '';
745	  if (Object.prototype.hasOwnProperty.call(data, 'summary')) {
746	    if (typeof data.summary !== 'string') throw new HttpError(400, 'summary must be a string when provided');
747	    summary = data.summary;
748	  }
749	  if (typeof data.body !== 'string') {
750	    throw new HttpError(400, 'body must be a string');
751	  }
752	  return { title, summary, body: data.body };
753	}
754	
755	// Updates carry the version the editor loaded; stale versions are rejected.
756	// As with creation, summary may be omitted (saved as empty string) but a
757	// present non-string summary is a 400.
758	function validateUpdateInput(data: Record<string, unknown>): DraftInput & { version: number } {
759	  const fields = validateDraftInput(data);
760	  if (typeof data.version !== 'number' || !Number.isInteger(data.version) || data.version < 0) {
761	    throw new HttpError(400, 'version must be a non-negative integer');
762	  }
763	  return { ...fields, version: data.version };
764	}
765	
766	async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
767	  let route: string;
768	  try { route = new URL(req.url ?? '/', 'http://localhost').pathname; }
769	  catch { respond(res, 400, { error: 'invalid request path' }); return; }
770	
771	  // /api/articles/:id (match the raw path first; decode only the captured id)
772	  const itemMatch = /^\/api\/articles\/([^/]+)$/.exec(route);
773	  let itemId: string | null = null;
774	  if (itemMatch) {
775	    try { itemId = decodeURIComponent(itemMatch[1]); }
776	    catch { respond(res, 400, { error: 'invalid article id encoding' }); return; }
777	  }
778	
779	  if (!['/', '/health', '/api/articles'].includes(route) && !itemMatch) {
780	    respond(res, 404, { error: 'not found' });
781	    return;
782	  }
783	
784	  if (route === '/') {
785	    if (req.method === 'GET') { respond(res, 200, PAGE, true); return; }
786	    methodNotAllowed(res, 'GET');
787	    return;
788	  }
789	  if (route === '/health') {
790	    if (req.method === 'GET') { respond(res, 200, { status: 'ok', product: PRODUCT }); return; }
791	    methodNotAllowed(res, 'GET');
792	    return;
793	  }
794	
795	  if (itemMatch && itemId !== null) {
796	    const id = itemId;
797	    if (req.method === 'GET') {
798	      const articles = readArticles();
799	      const article = articles.find((a) => a.id === id);
800	      if (!article) throw new HttpError(404, 'article not found');
801	      respond(res, 200, { article });
802	      return;
803	    }
804	    if (req.method === 'PUT') {
805	      const text = await readBody(req);
806	      const data = parseJsonObject(text);
807	      const fields = validateUpdateInput(data);
808	      const result = await enqueueWrite((): { status: number; article: Article } => {
809	        const records = readArticles();
810	        const index = records.findIndex((a) => a.id === id);
811	        if (index === -1) {
812	          throw new HttpError(404, 'article not found');
813	        }
814	        const current = records[index];
815	        if (fields.version !== current.version) {
816	          // 409 carries the currently saved article for side-by-side comparison.
817	          const conflict = new HttpError(409, 'a newer version of this article has been saved');
818	          (conflict as HttpError & { article?: Article }).article = current;
819	          throw conflict;
820	        }
821	        const updated: Article = {
822	          id: current.id,
823	          title: fields.title,
824	          summary: fields.summary,
825	          body: fields.body,
826	          status: current.status,
827	          createdAt: current.createdAt,
828	          version: current.version + 1,
829	        };
830	        records[index] = updated;
831	        writeArticles(records);
832	        return { status: 200, article: updated };
833	      });
834	      respond(res, result.status, { article: result.article });
835	      return;
836	    }
837	    methodNotAllowed(res, 'GET, PUT');
838	    return;
839	  }
840	
841	  // /api/articles
842	  if (req.method === 'GET') {
843	    respond(res, 200, { [RESOURCE]: readArticles() });
844	    return;
845	  }
846	  if (req.method === 'POST') {
847	    const text = await readBody(req);
848	    const data = parseJsonObject(text);
849	    const fields = validateDraftInput(data);
850	    const article: Article = {
851	      id: randomUUID(),
852	      title: fields.title,
853	      summary: fields.summary,
854	      body: fields.body,
855	      status: 'draft',
856	      createdAt: new Date().toISOString(),
857	      version: 1,
858	    };
859	    await enqueueWrite((): void => {
860	      const records = readArticles();
861	      records.push(article);
862	      writeArticles(records);
863	    });
864	    respond(res, 201, { article });
865	    return;
866	  }
867	  methodNotAllowed(res, 'GET, POST');
868	}
869	
870	const server = createServer((req: IncomingMessage, res: ServerResponse): void => {
871	  handle(req, res).catch((error: unknown) => {
872	    if (res.writableEnded) return;
873	    if (error instanceof HttpError) {
874	      const payload: { error: string; article?: Article } = { error: error.message };
875	      const withArticle = error as HttpError & { article?: Article };
876	      if (error.status === 409 && withArticle.article) payload.article = withArticle.article;
877	      respond(res, error.status, payload);
878	      return;
879	    }
880	    respond(res, 500, { error: error instanceof Error ? error.message : 'internal error' });
881	  });
882	});
883	server.once('error', (error: Error): void => { console.error(error.message); process.exitCode = 1; });
884	server.listen(port, host, (): void => {
885	  const address = server.address();
886	  if (address && typeof address !== 'string') {
887	    const displayedHost = address.address.includes(':') ? `[${address.address}]` : address.address;
888	    console.log(`${PRODUCT} listening on http://${displayedHost}:${address.port}`);
889	  }
890	});
891	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
892	  process.on(signal, (): void => { server.close(() => { process.exitCode = 0; }); server.closeIdleConnections(); });
893	}
