// Verification harness for the oversized-request fix.
import { connect } from 'node:net';

const HOST = '127.0.0.1';
const PORT = 18080;
const MAX = 5 * 1024 * 1024;

let failures = 0;
function check(name, cond, extra) {
  if (cond) {
    console.log('PASS', name);
  } else {
    failures++;
    console.log('FAIL', name, extra !== undefined ? JSON.stringify(extra) : '');
  }
}

async function httpRaw(requestBytes, { chunkDelay = 0, chunkSize = 64 * 1024 } = {}) {
  return await new Promise((resolve, reject) => {
    const sock = connect(PORT, HOST);
    let received = Buffer.alloc(0);
    let sendOffset = 0;
    let settled = false;
    sock.on('connect', () => pump());
    sock.on('data', (d) => { received = Buffer.concat([received, d]); });
    sock.on('end', () => { if (!settled) { settled = true; resolve({ received, reset: false }); } });
    sock.on('close', (hadErr) => {
      if (!settled) { settled = true; resolve({ received, reset: hadErr || received.length === 0 }); }
    });
    sock.on('error', (err) => { if (!settled) { settled = true; reject(err); } });
    function pump() {
      if (sendOffset >= requestBytes.length) { sock.end(); return; }
      const piece = requestBytes.subarray(sendOffset, sendOffset + chunkSize);
      sendOffset += piece.length;
      sock.write(piece);
      if (chunkDelay > 0) setTimeout(pump, chunkDelay);
      else pump();
    }
  });
}

// Parse a raw HTTP response: { status, headers, body, bodyBytes }
function parseResponse(buf) {
  const sep = Buffer.from('\r\n\r\n');
  const idx = buf.indexOf(sep);
  if (idx < 0) return null;
  const head = buf.subarray(0, idx).toString('latin1');
  const lines = head.split('\r\n');
  const statusLine = lines[0] || '';
  const m = /^HTTP\/1\.[01] (\d{3})/.exec(statusLine);
  const headers = Object.create(null);
  for (const line of lines.slice(1)) {
    const ci = line.indexOf(':');
    if (ci > 0) headers[line.slice(0, ci).trim().toLowerCase()] = line.slice(ci + 1).trim();
  }
  return { status: m ? Number(m[1]) : 0, headers, body: buf.subarray(idx + 4) };
}

function jsonRequest(method, path, payload) {
  const body = Buffer.from(payload, 'utf8');
  const head = Buffer.from(
    `${method} ${path} HTTP/1.1\r\nHost: ${HOST}:${PORT}\r\nContent-Type: application/json\r\nContent-Length: ${body.length}\r\nConnection: close\r\n\r\n`,
    'latin1');
  return Buffer.concat([head, body]);
}
function chunkedRequest(method, path, body) {
  const head = Buffer.from(
    `${method} ${path} HTTP/1.1\r\nHost: ${HOST}:${PORT}\r\nContent-Type: application/json\r\nTransfer-Encoding: chunked\r\nConnection: close\r\n\r\n`,
    'latin1');
  return Buffer.concat([head, body, Buffer.from('0\r\n\r\n')]);
}
// Build a JSON body string of exactly `target` UTF-8 bytes.
function bodyOfSize(target, fields = {}) {
  const marker = '"__PAD__"';
  fields.__PAD__ = '';
  const base = JSON.stringify(fields).replace(`"__PAD__":""`, `"__PAD__":${marker}`);
  const [pre, post] = base.split(marker);
  const padLen = target - Buffer.byteLength(pre, 'utf8') - Buffer.byteLength(post, 'utf8');
  if (padLen < 0) throw new Error('fields already exceed target');
  return pre + 'a'.repeat(padLen) + post;
}
function expectError(raw, label) {
  check(label + ': socket returned data, no reset', !raw.reset && raw.received.length > 0, { len: raw.received.length });
  const res = parseResponse(raw.received);
  check(label + ': response parseable', !!res);
  if (!res) return null;
  check(label + ': status 400', res.status === 400, res.status);
  check(label + ': content-type json', /application\/json/.test(res.headers['content-type'] || ''), res.headers['content-type']);
  // Body must be fully readable per declared length (complete response).
  const declared = Number(res.headers['content-length']);
  check(label + ': content-length present and body complete',
    Number.isFinite(declared) && res.body.length === declared, { declared, actual: res.body.length });
  let json = null;
  try { json = JSON.parse(res.body.toString('utf8')); } catch { /* */ }
  check(label + ': JSON object with non-empty error mentioning size',
    !!json && typeof json === 'object' && typeof json.error === 'string' && json.error.length > 0
      && /size|大小/i.test(json.error), json && json.error);
  return json;
}

async function api(method, path, obj) {
  const raw = await httpRaw(jsonRequest(method, path, JSON.stringify(obj)));
  const res = parseResponse(raw.received);
  let json = null;
  try { json = JSON.parse(res.body.toString('utf8')); } catch { /* */ }
  return { status: res.status, json };
}

const run = async () => {
  // --- 1. exactly at limit: succeeds (POST, content-length) ---
  const exact = bodyOfSize(MAX, { title: '刚好上限', summary: '', body: '' });
  check('exact-limit body byte count', Buffer.byteLength(exact, 'utf8') === MAX);
  let raw = await httpRaw(jsonRequest('POST', '/api/articles', exact));
  let res = parseResponse(raw.received);
  check('exact-limit POST succeeds 201', res.status === 201, res.status);
  let saved;
  try { saved = JSON.parse(res.body.toString('utf8')).article; } catch { /* */ }
  check('exact-limit returned article', !!saved && saved.version === 1);

  // --- 2. one byte over: rejected (content-length) ---
  const over = bodyOfSize(MAX + 1, { title: '超出一字节', summary: '', body: '' });
  check('over-limit byte count', Buffer.byteLength(over, 'utf8') === MAX + 1);
  raw = await httpRaw(jsonRequest('POST', '/api/articles', over));
  expectError(raw, 'POST content-length over by 1');

  // --- 3. chunked, far over limit, sent slowly AFTER the limit is crossed ---
  // Build chunked framing manually with delays between data chunks.
  {
    const huge = bodyOfSize(MAX + 123456, { title: '分块超限', summary: '', body: '' });
    const head = Buffer.from(
      `POST /api/articles HTTP/1.1\r\nHost: ${HOST}:${PORT}\r\nContent-Type: application/json\r\nTransfer-Encoding: chunked\r\nConnection: close\r\n\r\n`,
      'latin1');
    const tail = Buffer.from('0\r\n\r\n');
    const out = await new Promise((resolve, reject) => {
      const sock = connect(PORT, HOST);
      let received = Buffer.alloc(0);
      let done = false;
      sock.on('data', (d) => { received = Buffer.concat([received, d]); });
      sock.on('close', () => { if (!done) { done = true; resolve(received); } });
      sock.on('error', reject);
      sock.write(head);
      const CH = 64 * 1024;
      let off = 0;
      const step = () => {
        if (off >= huge.length) {
          sock.write(tail);
          sock.end();
          return;
        }
        const piece = Buffer.from(huge.slice(off, off + CH), 'utf8');
        off += piece.length;
        sock.write(Buffer.from(`${piece.length.toString(16)}\r\n`, 'latin1'));
        sock.write(piece);
        sock.write(Buffer.from('\r\n'));
        // keep sending well after server has crossed the limit
        setTimeout(step, 2);
      };
      step();
    });
    const rawRes = { received: out, reset: false };
    expectError(rawRes, 'POST chunked +123KiB slow after limit');
  }

  // --- 4. declared content-length over limit, body actually sent (drain path) ---
  {
    const huge = bodyOfSize(MAX + 5000, { title: '声明长度超限', summary: '', body: '' });
    raw = await httpRaw(jsonRequest('POST', '/api/articles', huge), { chunkDelay: 1, chunkSize: 32 * 1024 });
    expectError(raw, 'POST content-length declared over, drained slowly');
  }

  // --- 5. UTF-8 counting: 2 MiB worth of CJK chars = 6 MiB bytes => rejected ---
  {
    const cjk = '中'.repeat(2 * 1024 * 1024);
    const obj = JSON.stringify({ title: '中文文章', body: cjk });
    check('CJK payload byte size > limit', Buffer.byteLength(obj, 'utf8') > MAX);
    raw = await httpRaw(jsonRequest('POST', '/api/articles', obj), { chunkDelay: 1, chunkSize: 128 * 1024 });
    expectError(raw, 'POST CJK multi-byte over limit');
  }

  // --- 6. multibyte payload that fits in 5 MiB bytes: accepted ---
  {
    // 1.5M CJK chars = 4.5 MiB, plus JSON overhead stays under 5 MiB.
    const obj = JSON.stringify({ title: 't', body: '中'.repeat(1_500_000) });
    check('CJK fit byte size', Buffer.byteLength(obj, 'utf8') < MAX);
    raw = await httpRaw(jsonRequest('POST', '/api/articles', obj), {});
    res = parseResponse(raw.received);
    check('CJK fit POST 201', res.status === 201, res.status);
  }

  // --- 7. PUT over limit: existing article unchanged, 400 complete ---
  const created = await api('POST', '/api/articles', JSON.stringify({
    title: '  原标题  ', summary: '原摘要', body: '原正文\n第二段',
  }));
  check('setup create 201', created.status === 201, created.status);
  const id = created.json.article.id;
  const before = created.json.article;

  const putOver = bodyOfSize(MAX + 1, { title: '超限修改', summary: 'x', body: '', version: 1 });
  raw = await httpRaw(jsonRequest('PUT', `/api/articles/${id}`, putOver));
  expectError(raw, 'PUT content-length over limit');

  // chunked PUT too, slow after crossing limit
  raw = await httpRaw(chunkedRequest('PUT', `/api/articles/${id}`, Buffer.from(bodyOfSize(MAX + 7777, { title: '分块改', summary: '', body: '', version: 1 }), 'utf8')),
    { chunkDelay: 1, chunkSize: 16 * 1024 });
  expectError(raw, 'PUT chunked over limit');

  const after = await api('GET', `/api/articles/${id}`, null);
  check('GET after rejected PUT still 200', after.status === 200, after.status);
  const a = after.json.article;
  check('id unchanged', a.id === before.id);
  check('title unchanged', a.title === before.title, [a.title, before.title]);
  check('summary unchanged', a.summary === before.summary);
  check('body unchanged', a.body === before.body);
  check('createdAt unchanged', a.createdAt === before.createdAt);
  check('version unchanged (still 1)', a.version === before.version && a.version === 1, a.version);

  // --- 8. no new draft created by rejections: list contains exactly 3 (exact, cjk-fit, setup) ---
  const list = await api('GET', '/api/articles', null);
  check('list 200', list.status === 200);
  check('list count == 3 (no drafts from rejected creates)', list.json.articles.length === 3, list.json.articles.map((x) => x.id));

  // --- 9. subsequent valid PUT still works, version conflict rules intact ---
  const okPut = await api('PUT', `/api/articles/${id}`, JSON.stringify({
    title: '  新标题  ', summary: '', body: '新正文\n\n<html>原样</html>', version: 1,
  }));
  check('valid PUT after rejection is 200', okPut.status === 200, okPut.status);
  check('valid PUT version -> 2', okPut.json.article.version === 2, okPut.json.article.version);
  check('title trimmed', okPut.json.article.title === '新标题');
  check('summary cleared', okPut.json.article.summary === '');
  check('body preserved verbatim', okPut.json.article.body === '新正文\n\n<html>原样</html>');
  check('id/createdAt preserved on PUT', okPut.json.article.id === id && okPut.json.article.createdAt === before.createdAt);

  const stale = await api('PUT', `/api/articles/${id}`, JSON.stringify({
    title: '旧版本', summary: '', body: '', version: 1,
  }));
  check('stale version -> 409', stale.status === 409, stale.status);
  check('409 carries current saved article', !!(stale.json.article && stale.json.article.version === 2));

  // --- 10. validation rules unchanged for normal requests ---
  const bad1 = await api('POST', '/api/articles', JSON.stringify({ title: '   ', body: '' }));
  check('blank title 400', bad1.status === 400 && bad1.json.error, bad1.status);
  const bad2 = await api('POST', '/api/articles', JSON.stringify({ title: 'x', body: 123 }));
  check('non-string body 400', bad2.status === 400 && bad2.json.error, bad2.status);
  const emptyBody = await api('POST', '/api/articles', JSON.stringify({ title: '空正文', body: '' }));
  check('empty body allowed 201', emptyBody.status === 201, emptyBody.status);
  const noSummary = await api('POST', '/api/articles', JSON.stringify({ title: '无摘要', body: 'x' }));
  check('summary omitted saved empty', noSummary.status === 201 && noSummary.json.article.summary === '');
  const malformed = await new Promise(async () => {}); // placeholder no-op
  void malformed;

  console.log(failures === 0 ? '\nALL TESTS PASSED' : `\n${failures} FAILURE(S)`);
  process.exit(failures === 0 ? 0 : 1);
};

run().catch((e) => { console.error('HARNESS ERROR', e); process.exit(2); });

