  const marker='PADMARKERTOKEN'; fields.PADKEY=marker;
  const base=JSON.stringify(fields);
  const [pre,post]=base.split(marker);
  return pre+'a'.repeat(target-Buffer.byteLength(pre)-Buffer.byteLength(post))+post;
}
const sock = connect(18080,'127.0.0.1');
let buf = Buffer.alloc(0);
let pending = 0;
const responses = [];
sock.on('data', d => {
  buf = Buffer.concat([buf, d]);
  // parse responses as they complete (simple framing via content-length)
  while (true) {
    const sep = buf.indexOf('\r\n\r\n');
    if (sep < 0) break;
    const head = buf.subarray(0,sep).toString('latin1');
    const m = /content-length: (\d+)/i.exec(head);
    const cl = m ? Number(m[1]) : 0;
    if (buf.length < sep+4+cl) break;
    const body = buf.subarray(sep+4, sep+4+cl).toString('utf8');
    responses.push({ status: Number(head.match(/HTTP\/1\.[01] (\d{3})/)[1]), body });
    buf = buf.subarray(sep+4+cl);
    if (--pending === 0) {
      console.log(responses.map(r => r.status + ' ' + r.body.slice(0,80)).join('\n'));
      sock.end(); process.exit(0);
    }
  }
});
function req(method, path, bodyText) {
  pending++;
  const b = Buffer.from(bodyText, 'utf8');
  sock.write(\`\${method} \${path} HTTP/1.1\r\nHost: x\r\nContent-Type: application/json\r\nContent-Length: \${b.length}\r\n\r\n\`);
  sock.write(b);
}
await new Promise(r => sock.on('connect', r));
